import{_ as a,o as i,c as s,a0 as o}from"./chunks/framework.DhQjJcnt.js";const u=JSON.parse('{"title":"Troubleshooting FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"en/faq.md","filePath":"en/faq.md","lastUpdated":1787985369000}'),t={name:"en/faq.md"};function r(n,e,l,d,h,c){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="troubleshooting-faq" tabindex="-1">Troubleshooting FAQ <a class="header-anchor" href="#troubleshooting-faq" aria-label="Permalink to &quot;Troubleshooting FAQ&quot;">​</a></h1><h2 id="connection-issues" tabindex="-1">Connection issues <a class="header-anchor" href="#connection-issues" aria-label="Permalink to &quot;Connection issues&quot;">​</a></h2><h3 id="guest-room-not-found-or-expired-xxx" tabindex="-1">Guest: <code>room not found or expired: xxx</code> <a class="header-anchor" href="#guest-room-not-found-or-expired-xxx" aria-label="Permalink to &quot;Guest: `room not found or expired: xxx`&quot;">​</a></h3><ul><li>Wrong room code (case-sensitive)</li><li>Room expired (default 12h) or closed by the host&#39;s Ctrl-C</li><li>Ask the host to run <code>game create</code> again for a fresh code</li></ul><h3 id="guest-udp-echo-timed-out" tabindex="-1">Guest: <code>UDP echo timed out</code> <a class="header-anchor" href="#guest-udp-echo-timed-out" aria-label="Permalink to &quot;Guest: `UDP echo timed out`&quot;">​</a></h3><p>The client cannot reach the server&#39;s UDP probe port:</p><ul><li>Check <code>8080/udp</code> is opened (cloud security group <strong>and</strong> OS firewall)</li><li>Check <code>signaling_addr</code> points at the right server</li><li>Verify with <code>nc -u SERVER-IP 8080</code> or any UDP client sending <code>ECHO test</code></li></ul><h3 id="stuck-at-udp-hole-punching-failed-falling-back-to-relay" tabindex="-1">Stuck at <code>UDP hole punching failed, falling back to relay ...</code> <a class="header-anchor" href="#stuck-at-udp-hole-punching-failed-falling-back-to-relay" aria-label="Permalink to &quot;Stuck at `UDP hole punching failed, falling back to relay ...`&quot;">​</a></h3><p>Punch failure is normal for strict NATs and <strong>does not break usage</strong> — it falls back to relay automatically. To get direct:</p><ul><li>Try a larger <code>--spread</code> (symmetric NAT)</li><li>Make sure UDP outbound works on both sides</li><li>If both ends are behind the same NAT/LAN, public-IP punching is a hairpin case and may fail — use <code>--relay</code></li></ul><h3 id="direct-link-established-but-no-data-flows" tabindex="-1">Direct link established but no data flows <a class="header-anchor" href="#direct-link-established-but-no-data-flows" aria-label="Permalink to &quot;Direct link established but no data flows&quot;">​</a></h3><ul><li>Confirm the host&#39;s <code>--service</code> process is <strong>running</strong> and listening on the right port</li><li>Confirm the guest&#39;s <code>--listen</code> port is not occupied</li><li>Run with <code>--verbose</code> and check whether frames are flowing</li></ul><h3 id="decryption-failed-wrong-key" tabindex="-1"><code>decryption failed (wrong --key?)</code> <a class="header-anchor" href="#decryption-failed-wrong-key" aria-label="Permalink to &quot;`decryption failed (wrong --key?)`&quot;">​</a></h3><p>The two sides&#39; <code>--key</code> passphrases differ (or one side omitted it). Align them and recreate the room.</p><h2 id="deployment-issues" tabindex="-1">Deployment issues <a class="header-anchor" href="#deployment-issues" aria-label="Permalink to &quot;Deployment issues&quot;">​</a></h2><h3 id="server-port-already-in-use" tabindex="-1">Server: port already in use <a class="header-anchor" href="#server-port-already-in-use" aria-label="Permalink to &quot;Server: port already in use&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AddrInUse</span></span></code></pre></div><ul><li><code>8080</code> or <code>8081</code> is taken by another process; change ports:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.0.0.0:9000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --relay-addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.0.0.0:9001</span></span></code></pre></div></li><li>Update the client config accordingly (<code>http://IP:9000</code>, <code>IP:9001</code>)</li></ul><h3 id="windows-quick-restart-fails-with-a-socket-permission-error" tabindex="-1">Windows: quick restart fails with a socket permission error <a class="header-anchor" href="#windows-quick-restart-fails-with-a-socket-permission-error" aria-label="Permalink to &quot;Windows: quick restart fails with a socket permission error&quot;">​</a></h3><p>After a TCP listener closes, Windows briefly holds the port in a transitional state; immediately re-binding UDP on the same port can fail:</p><ul><li>Wait 2–3 seconds before restarting</li><li>Or use a separate UDP probe port (<code>signaling_udp</code> + a dedicated server listener)</li></ul><h2 id="performance-stability" tabindex="-1">Performance &amp; stability <a class="header-anchor" href="#performance-stability" aria-label="Permalink to &quot;Performance &amp; stability&quot;">​</a></h2><h3 id="slow-transfers" tabindex="-1">Slow transfers <a class="header-anchor" href="#slow-transfers" aria-label="Permalink to &quot;Slow transfers&quot;">​</a></h3><ul><li>The reliable stream window is 32 × 1200 B ≈ 38 KB in flight; high-latency links are throughput-limited</li><li>Relay mode is capped by the server&#39;s egress</li><li>Direct punching is generally faster (one less hop)</li></ul><h3 id="connection-dies-after-long-idle" tabindex="-1">Connection dies after long idle <a class="header-anchor" href="#connection-dies-after-long-idle" aria-label="Permalink to &quot;Connection dies after long idle&quot;">​</a></h3><p>NAT mappings expire (usually 30–120 s). frp-sh sends keepalive ACKs every second, so this normally doesn&#39;t happen; if your NAT has an extremely short timeout, keep a trickle of data flowing.</p><h3 id="frames-dropped-under-heavy-load" tabindex="-1">Frames dropped under heavy load <a class="header-anchor" href="#frames-dropped-under-heavy-load" aria-label="Permalink to &quot;Frames dropped under heavy load&quot;">​</a></h3><p>The read buffer caps at 1 MB; beyond that frames are dropped and recovered by retransmit (go-back-N flow control). Expected behavior — correctness is unaffected.</p><h2 id="security-questions" tabindex="-1">Security questions <a class="header-anchor" href="#security-questions" aria-label="Permalink to &quot;Security questions&quot;">​</a></h2><h3 id="is-relay-mode-safe" tabindex="-1">Is relay mode safe? <a class="header-anchor" href="#is-relay-mode-safe" aria-label="Permalink to &quot;Is relay mode safe?&quot;">​</a></h3><p>Relay traffic is <strong>plaintext</strong> (it passes through your signaling server). For confidentiality:</p><ul><li>Prefer direct punching + <code>--key</code></li><li>Or wrap the path to the server yourself (e.g., WireGuard)</li></ul><h3 id="can-room-codes-be-guessed" tabindex="-1">Can room codes be guessed? <a class="header-anchor" href="#can-room-codes-be-guessed" aria-label="Permalink to &quot;Can room codes be guessed?&quot;">​</a></h3><p>The code body is 6 hex chars (~16M combinations) with a 12h TTL; brute-forcing means hitting the server millions of times in a short window — low risk but nonzero. For higher assurance:</p><ul><li>Use a longer custom prefix: <code>frp-sh game create --prefix my-long-room-2024</code></li><li>Add <code>--key</code> (even if the code leaks, the traffic stays encrypted)</li></ul><h2 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h2><h3 id="invalid-room-id-rules" tabindex="-1"><code>invalid room id</code> rules <a class="header-anchor" href="#invalid-room-id-rules" aria-label="Permalink to &quot;`invalid room id` rules&quot;">​</a></h3><p>Format: <code>prefix-6hex</code> (e.g., <code>game-a3f9c2</code>). <code>--prefix</code> keeps only lowercase alphanumerics and <code>-_</code>, max 16 chars.</p><h3 id="how-does-a-session-end" tabindex="-1">How does a session end? <a class="header-anchor" href="#how-does-a-session-end" aria-label="Permalink to &quot;How does a session end?&quot;">​</a></h3><p><code>Ctrl-C</code> on either side; or automatically when <code>--max-conns</code> is exhausted. The host deletes the room on exit.</p><h3 id="ipv6-support" tabindex="-1">IPv6 support? <a class="header-anchor" href="#ipv6-support" aria-label="Permalink to &quot;IPv6 support?&quot;">​</a></h3><p>Signaling, relay, and punching all use standard <code>SocketAddr</code> and support IPv6 (<code>[::1]:8080</code> form in config). Punching behavior depends on the actual network.</p><h3 id="can-it-run-in-docker" tabindex="-1">Can it run in Docker? <a class="header-anchor" href="#can-it-run-in-docker" aria-label="Permalink to &quot;Can it run in Docker?&quot;">​</a></h3><p>Yes — the static binary drops straight into an image:</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ubuntu:24.04</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> frp-sh /usr/local/bin/frp-sh</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">EXPOSE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 8080/tcp 8080/udp 8081/tcp</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CMD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;frp-sh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;serve&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0.0:8080&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--relay-addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0.0:8081&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h2 id="feedback" tabindex="-1">Feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Feedback&quot;">​</a></h2><p>If something is not covered, report it with <code>frp-sh --verbose</code> output and a description of the network environment.</p>',47)])])}const k=a(t,[["render",r]]);export{u as __pageData,k as default};
